WITH allocations AS (SELECT contract_id,count(*) n,sum(closing_value) allocated,min(contract_value_full) full_value,min(n_winners) declared FROM marts.contract_transactions GROUP BY 1), summary AS (
SELECT count(*) contracts,sum(n) allocations,sum(n)-count(*) extra_rows,sum(allocated) allocated,sum(full_value) full_value,count(*) FILTER(WHERE allocated<>full_value) bad_sum,count(*) FILTER(WHERE n<>declared) bad_winners FROM allocations)
SELECT 'allocations' test,to_jsonb(summary) data FROM summary
UNION ALL SELECT 'currencies',jsonb_agg(x) FROM (SELECT coalesce(currency,'NULL') currency,count(*) n,sum(contract_value) total,min(contract_value) minimum,max(contract_value) maximum FROM core.contracts GROUP BY 1 ORDER BY 2 DESC) x
UNION ALL SELECT 'cpv_disagreement',to_jsonb(x) FROM (SELECT count(*) n,count(*) FILTER(WHERE left(c.cpv_code,2)<>left(aw.cpv_code,2)) different_division,count(*) FILTER(WHERE ct.contract_id IS NOT NULL) in_marts FROM core.contracts c JOIN core.awards aw USING(ca_notice_id) LEFT JOIN allocations ct ON ct.contract_id=c.id WHERE c.cpv_code IS NOT NULL AND c.cpv_code IS DISTINCT FROM aw.cpv_code) x
UNION ALL SELECT 'missing_winners',to_jsonb(x) FROM (SELECT count(*) n,sum(contract_value) amount FROM core.contracts c WHERE c.contract_value>0 AND c.contract_value<=100000000000 AND (currency IS NULL OR currency ILIKE '%ron%') AND NOT EXISTS (SELECT 1 FROM core.contract_winners w WHERE w.contract_id=c.id)) x
